// 1631:0F24: Register word16 Combat_Calculate_RangeBracket(Register Eq_21 ds, Stack Eq_21 MechLanceId, Stack Eq_21 Mech_CurrentActuators)
// Called from:
//      Combat_Weapon_UI_0004
//      Combat_Select_Weapon_Target_UI
//      Combat_Mechanics
// Sol: Summary: Determine a weapon's range bracket.
// Sol: Outline: Adjust for target footprint, calculate packed-world distance, and compare the weapon's range limits.
unsigned short Combat_Calculate_RangeBracket(unsigned short TargetId, unsigned short WeaponId)
{
	// Sol: Fresh whole-body ASM comparison2026-09-17: locally matched under
	// Sol: native WORD/FAR and shared-call contracts; see systematic segment report.
	// Sol: WORD positions preserve region nibbles; WeaponId is a table index,
	// Sol: not a component code. Typed arrays already account for record stride.
	unsigned short Target_MechPosX = seg3092->CombatantPackedX[TargetId]; //DS:4004
	unsigned short Target_MechPosY = seg3092->CombatantPackedY[TargetId]; //DS:4036

	if (((short)TargetId < Friendly_Infantry_Combatant_Range_First
		|| ((short)TargetId >= Enemy_All_CombatantId_Range_First && (short)TargetId <= Enemy_Mech_CombatantId_Range_Last))
		&& (short)Combat_Operation_0BB5(Target_MechPosX, Target_MechPosY) > 3) // Sol: distant mech footprint correction; signed ASM ID/distance tests
	{
		if (seg246C->CrescentHawk_MapPositionX < Target_MechPosX) //A44B - Character Position X 
		{
			Target_MechPosX = Target_MechPosX - 0x01;

			if ((Target_MechPosX & 0x80) != 0x00)
				Target_MechPosX &= 0x0F7F;
		}

		if (seg246C->CrescentHawk_MapPositionX > Target_MechPosX) //A44B - Character Position X 
		{
			Target_MechPosX++;

			if ((Target_MechPosX & 0x80) != 0x00)
				Target_MechPosX += 0x80;
		}

		if (seg246C->CrescentHawk_MapPositionY < Target_MechPosY) //A44D - Character position Y
		{
			Target_MechPosY -= 0x02;

			if ((Target_MechPosY & 0x80) != 0x00)
				Target_MechPosY &= 0xF07F;
		}
	}

	unsigned short DistanceToTarget = Combat_Operation_0BB5(Target_MechPosX, Target_MechPosY);
	unsigned short SelectedRangeBracket = RangeBracket_OutOfRange; //Out of Range Bracket

	

	// Sol: All boundaries are strict (<); equality with maximum is out of range.
	// Sol: Only short/medium thresholds are scaled here; maximum is pre-scaled.
	if (seg3EDB->WeaponStats[WeaponId].MaximumRange > DistanceToTarget)
		SelectedRangeBracket = RangeBracket_Long; // Long range bracket

	unsigned short PackedWeaponRange = seg3EDB->WeaponStats[WeaponId].RangeBracket;
	unsigned short MediumRange = PackedWeaponRange & 0x1F;
	unsigned short ShortRange = PackedWeaponRange >> 0x05;

	//If MECH weaponry (< 80) then rescale range by 3x
	if (seg3EDB->WeaponStats[WeaponId].WeaponType < InfantryWeapons && WeaponId != (Mech_Kick - 1))
	{
		MediumRange = (PackedWeaponRange & 0x1F) * InfantryToMechGridScaling; //0x03 is for 8px character scaling to Mech Scaling
		ShortRange = (PackedWeaponRange >> 0x05) * InfantryToMechGridScaling; //0x03 is for 8px character scaling to Mech Scaling
	}

	if (DistanceToTarget < MediumRange)
		SelectedRangeBracket = RangeBracket_Medium; //Medium Range Bracket

	if (DistanceToTarget < ShortRange)
		SelectedRangeBracket = RangeBracket_Short; //Short Range Bracket

	return SelectedRangeBracket;
}

