			break;

		case 0x1C: // Sol: left-arm structure
		case 0x1E: // Sol: left-leg structure -> FRONT left-torso armour, not structure
			DamageLocation = 0x12;
			break;

		case 0x1D: // Sol: left-torso structure
		case 0x22: // Sol: right-torso structure -> FRONT center-torso armour
